                                                        <div className="w-7 h-7 bg-white/5 rounded flex items-center justify-center text-[10px] font-black tracking-tighter select-none">
                                                            {getInitials(match.away_team?.name || '')}
                                                        </div>
                                                    )
                                                )}
                                                <span className="font-extrabold tracking-tight text-white text-base max-w-[120px] truncate relative">
                                                    <span>{teamNameMode === "abbr" ? getInitials(match.away_team?.name || '') : match.away_team?.name}</span>
                                                    {renderRedCards(awayRedCards)}
                                                </span>
                                            </div>

                                            {/* Timer / Status Area */}
                                            <div className="flex items-center justify-center bg-white/5 border-l border-white/10 px-5 text-white h-full font-mono text-sm font-bold min-w-[95px]">
                                                {match.status === "finished" ? (
                                                    <span className="text-red-500 font-extrabold tracking-widest text-xs">FT</span>
                                                ) : isHalfTime ? (
                                                    <span className="text-amber-500 font-extrabold tracking-widest text-xs">HT</span>
                                                ) : match.status === "live" ? (
                                                    <span className={cn("text-emerald-400 font-bold", match.timer_status === "paused" && "text-amber-400")}>
                                                        {timeString}
                                                    </span>
                                                ) : (
                                                    <span className="text-white/60 text-xs font-extrabold tracking-wider">PRE</span>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                )}

                                {/* Minimal Corner Scoreboard Style */}
                                {(layout === "minimal-left" || layout === "minimal-right") && (
                                    <div className="bg-black/90 rounded-xl shadow-2xl p-3 flex flex-col gap-2 min-w-[240px]">
                                        {/* Header with Timer/Status */}
                                        <div className="flex items-center justify-between border-b border-white/5 pb-2 text-[10px] font-bold text-white/50 tracking-wider">
                                            <span>{displayHeaderText || "LEAGUEFLOW OVERLAY"}</span>
                                            <span className={cn("font-mono text-xs text-white", match.status === "live" && match.timer_status === "paused" && "text-amber-400")}>
                                                {match.status === "finished" ? "FULL TIME" : isHalfTime ? "HALF TIME" : match.status === "live" ? timeString : "UPCOMING"}
                                            </span>
                                        </div>

                                        {/* Home Row */}
                                        <div className="flex items-center justify-between">
                                            <div className="flex items-center gap-2">
                                                {showLogos && (
                                                    <div className="w-5 h-5 bg-white/5 rounded flex items-center justify-center overflow-hidden text-[8px] font-black tracking-tighter relative">
                                                        {match.home_team?.logo_url ? (
                                                            <Image src={match.home_team.logo_url} alt="" fill className="object-contain" unoptimized />
                                                        ) : (
                                                            <span>{getInitials(match.home_team?.name || '')}</span>
                                                        )}
                                                    </div>
                                                )}
                                                <span className="font-extrabold text-sm text-white tracking-tight relative">
                                                    <span>{teamNameMode === "abbr" ? getInitials(match.home_team?.name || '') : match.home_team?.name}</span>
                                                    {renderRedCards(homeRedCards)}
                                                </span>
                                            </div>
                                            <span className="font-black text-lg" style={{ color: scoreBg }}>{homeScore}</span>
                                        </div>

                                        {/* Away Row */}
                                        <div className="flex items-center justify-between">
                                            <div className="flex items-center gap-2">
                                                {showLogos && (
                                                    <div className="w-5 h-5 bg-white/5 rounded flex items-center justify-center overflow-hidden text-[8px] font-black tracking-tighter relative">
                                                        {match.away_team?.logo_url ? (
                                                            <Image src={match.away_team.logo_url} alt="" fill className="object-contain" unoptimized />
                                                        ) : (
                                                            <span>{getInitials(match.away_team?.name || '')}</span>
                                                        )}
                                                    </div>
                                                )}
                                                <span className="font-extrabold text-sm text-white tracking-tight relative">
                                                    <span>{teamNameMode === "abbr" ? getInitials(match.away_team?.name || '') : match.away_team?.name}</span>
                                                    {renderRedCards(awayRedCards)}
                                                </span>
                                            </div>
                                            <span className="font-black text-lg" style={{ color: scoreBg }}>{awayScore}</span>
                                        </div>
                                    </div>
                                )}
                            </>
                        )}

                        {/* Mini Goal Scorer Timeline Ticker Overlay */}
                        {showTimeline && goalEvents.length > 0 && (
                            <div className="flex flex-col gap-1 mt-2.5 max-h-[160px] overflow-hidden items-center select-none">
                                {goalEvents.slice(0, 3).map((e) => (
                                    <div key={e.id} className="flex items-center gap-2 bg-black/60 backdrop-blur-md rounded-full px-3 py-1.5 text-[10px] font-bold text-white/80 shadow-md">
                                        <Trophy className="w-3.5 h-3.5 text-emerald-400" />
                                        <span>{e.player_name} ({e.minute}&apos;)</span>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* Live Ticker Alert Popup Banner */}
            {searchParams.get("blocks") === null && (
                <div className={cn(
                    "absolute left-0 right-0 flex justify-center pointer-events-none z-50",
                    posY === "top" ? "bottom-10" : "top-10"
                )}>
                    <div
                        className={cn(
                            "transition-all duration-700 transform flex items-center gap-4 bg-black/95 border border-white/15 rounded-2xl shadow-[0_0_50px_rgba(0,0,0,0.8)] px-8 py-4 pointer-events-auto",
                            activeNotification
                                ? "translate-y-0 opacity-100 scale-100"
                                : posY === "top" ? "translate-y-10 opacity-0 scale-90" : "-translate-y-10 opacity-0 scale-90"
                        )}
                    >
                        {activeNotification?.type === "goal" && (
                            <>
                                <div className="w-12 h-12 rounded-full bg-emerald-500 flex items-center justify-center shadow-emerald-500/35 animate-bounce">
                                    <Trophy className="w-6 h-6 text-black fill-black" />
                                </div>
                                <div className="flex flex-col text-left">
                                    <span className="text-emerald-400 font-black text-2xl tracking-tighter leading-none">GOAL!</span>
                                    <span className="text-white font-extrabold text-lg mt-0.5 leading-none">
                                        {activeNotification.player}
                                    </span>
                                    <span className="text-white/50 font-bold text-xs mt-1">
                                        {activeNotification.teamName} • {activeNotification.minute}&apos;
                                    </span>
                                </div>
                            </>
                        )}

                        {(activeNotification?.type === "yellow_card" || activeNotification?.type === "red_card") && (
                            <>
                                <div
                                    className={cn(
                                        "w-10 h-12 rounded flex items-center justify-center transform rotate-6",
                                        activeNotification.type === "yellow_card"
                                            ? "bg-yellow-400 shadow-yellow-400/25"
                                            : "bg-red-600 shadow-red-600/25"
                                    )}
                                >
                                    <Square className={cn("w-5 h-6", activeNotification.type === "yellow_card" ? "text-black fill-black" : "text-white fill-white")} />
                                </div>
                                <div className="flex flex-col text-left">
                                    <span
                                        className={cn(
                                            "font-black text-2xl tracking-tighter leading-none",
                                            activeNotification.type === "yellow_card" ? "text-yellow-400" : "text-red-500"
                                        )}
                                    >
                                        {activeNotification.type === "yellow_card" ? "YELLOW CARD" : "RED CARD"}
                                    </span>
                                    <span className="text-white font-extrabold text-lg mt-0.5 leading-none">
                                        {activeNotification.player}
                                    </span>
                                    <span className="text-white/50 font-bold text-xs mt-1">
                                        {activeNotification.teamName} • {activeNotification.minute}&apos;
                                    </span>
                                </div>
                            </>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
}

export default function BroadcastOverlay() {
    return (
        <Suspense fallback={
            <div className="min-h-screen flex items-center justify-center text-white/50 text-xs font-mono select-none">
                Loading overlay...
            </div>
        }>
            <BroadcastOverlayContent />
        </Suspense>
    );
}

import React, { useState, useRef } from "react";
import { Button } from "@/components/ui/button";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Check, Plus, Shapes, Square, Circle, Triangle, Star, Type, ChevronDown } from "lucide-react";
import { CanvasBlock, getSnappedCoords } from "./types";
import { isLightColor } from "./helpers";

interface CanvasPreviewProps {
    bg: string;
    blocks: CanvasBlock[];
    setBlocks?: React.Dispatch<React.SetStateAction<CanvasBlock[]>>;
    selectedBlockId: string;
    setSelectedBlockId: (id: string) => void;
    scoreBg: string;
    homeBarDir: string;
    homeBarColor: string;
    awayBarDir: string;
    awayBarColor: string;
    headerText: string;
    blockGap: number;
    locale: string;
    toggleBlock: (index: number) => void;
    getBlockName: (id: string, name: string) => string;
    getShortPreviewLabel: (id: string) => string;
    onUpdateBlockPosition: (id: string, x: number, y: number) => void;
}

export function CanvasPreview({
    bg,
    blocks,
    setBlocks,
    selectedBlockId,
    setSelectedBlockId,
    scoreBg,
    homeBarDir,
    homeBarColor,
    awayBarDir,
    awayBarColor,
    headerText,
    blockGap,
    locale,
    toggleBlock,
    getBlockName,
    getShortPreviewLabel,
    onUpdateBlockPosition,
}: CanvasPreviewProps) {
    const [selectionBox, setSelectionBox] = useState<{ startX: number; startY: number; currentX: number; currentY: number; active: boolean } | null>(null);
    const [dragStart, setDragStart] = useState<{ pointerX: number; pointerY: number; initialBlocks: { id: string; x: number; y: number }[] } | null>(null);
    const [activeGuideLines, setActiveGuideLines] = useState<{ vLines: number[]; hLines: number[] } | null>(null);

    const selectedIds = (selectedBlockId || "").split(",").filter(Boolean);

    const handlePointerDown = (e: React.PointerEvent<HTMLDivElement>, id: string) => {
        e.preventDefault();
        e.stopPropagation();

        const clickedBlock = blocks.find(b => b.id === id);
        let idsToSelect: string[] = [id];

        if (clickedBlock?.groupId) {
            const groupMembers = blocks.filter(b => b.active && b.groupId === clickedBlock.groupId).map(b => b.id);
            if (groupMembers.length > 0) {
                idsToSelect = groupMembers;
            }
        }

        let currentSelectedIds = selectedIds;
        const isAllAlreadySelected = idsToSelect.every(bId => currentSelectedIds.includes(bId));

        if (!isAllAlreadySelected) {
            currentSelectedIds = idsToSelect;
            setSelectedBlockId(idsToSelect.join(","));
        }

        const initialBlocks = currentSelectedIds.map(bId => {
            const b = blocks.find(item => item.id === bId);
            return { id: bId, x: b?.x || 0, y: b?.y || 0 };
        });
        setDragStart({
            pointerX: e.clientX,
            pointerY: e.clientY,
            initialBlocks,
        });
        try {
            e.currentTarget.setPointerCapture(e.pointerId);
        } catch (_err) { }
    };

    const handlePointerMove = (e: React.PointerEvent<HTMLDivElement>, _id: string) => {
        if (!e.currentTarget.hasPointerCapture(e.pointerId) || !dragStart) return;
        const deltaX = e.clientX - dragStart.pointerX;
        const deltaY = e.clientY - dragStart.pointerY;

        const primaryInit = dragStart.initialBlocks[0];
        if (primaryInit) {
            const rawX = primaryInit.x + deltaX;
            const rawY = primaryInit.y + deltaY;
            const snapResult = getSnappedCoords(primaryInit.id, rawX, rawY, blocks, blockGap);
            const moveDeltaX = snapResult.x - primaryInit.x;
            const moveDeltaY = snapResult.y - primaryInit.y;

            setActiveGuideLines({
                vLines: snapResult.vLines,
                hLines: snapResult.hLines,
            });

            if (setBlocks) {
                setBlocks(prev => prev.map(b => {
                    const init = dragStart.initialBlocks.find(item => item.id === b.id);
                    if (init) {
                        return {
                            ...b,
                            x: Math.round((init.x + moveDeltaX) * 10) / 10,
                            y: Math.round((init.y + moveDeltaY) * 10) / 10,
                        };
                    }
                    return b;
                }));
            } else {
                dragStart.initialBlocks.forEach((item: { id: string; x: number; y: number }) => {
                    const newX = Math.round((item.x + moveDeltaX) * 10) / 10;
                    const newY = Math.round((item.y + moveDeltaY) * 10) / 10;
                    onUpdateBlockPosition(item.id, newX, newY);
                });
            }
        }
    };

    const handlePointerUp = (e: React.PointerEvent<HTMLDivElement>, _id: string) => {
        setDragStart(null);
        setActiveGuideLines(null);
        try {
            e.currentTarget.releasePointerCapture(e.pointerId);
        } catch (_err) { }
    };

    const handleAddShape = (shapeType: "rectangle" | "circle" | "polygon" | "star" | "text") => {
        const timestamp = Date.now();
        const names: Record<string, string> = {
            rectangle: locale === 'th' ? "สี่เหลี่ยม" : "Rectangle",
            circle: locale === 'th' ? "วงกลม" : "Circle",
            polygon: locale === 'th' ? "Polygon" : "Polygon",
            star: locale === 'th' ? "ดาว" : "Star",
            text: locale === 'th' ? "ข้อความ" : "Text",
        };

        const newShape: CanvasBlock = {
            id: `shape-${shapeType}-${timestamp}`,
            name: names[shapeType] || shapeType,
            active: true,
            x: 0,
            y: 0,
            w: shapeType === "text" ? 140 : 100,
            h: shapeType === "text" ? 40 : 100,
            fontSize: 16,
            rTL: shapeType === "circle" ? 50 : 0,
            rTR: shapeType === "circle" ? 50 : 0,
            rBL: shapeType === "circle" ? 50 : 0,
            rBR: shapeType === "circle" ? 50 : 0,
            opacity: 100,
            bg: shapeType === "text" ? "transparent" : "#737373",
            color: "#ffffff",
            shapeType: shapeType,
            text: shapeType === "text" ? (locale === 'th' ? "ข้อความใหม่" : "New Text") : undefined,
        };

        if (setBlocks) {
            setBlocks(prev => [...prev, newShape]);
        }
        setSelectedBlockId(newShape.id);
    };

    const getBlockDisplayContent = (b: CanvasBlock): string => {
        if (b.bindTo && b.bindTo !== "none") {
            switch (b.bindTo) {
                case "name-home": return locale === 'th' ? "ทีมเหย้า" : "HOME";
                case "name-away": return locale === 'th' ? "ทีมเยือน" : "AWAY";
                case "score-home": return "0";
                case "score-away": return "0";
                case "header-text": return headerText || "LEAGUEFLOW";
                case "timer": return "00:00";
                case "add-time": return "+0";
                case "logo-home": return "🛡️ Home";
                case "logo-away": return "🛡️ Away";
                case "logo-tournament": return "🛡️ Tour";
                case "home-scorer": return locale === 'th' ? "👟 A. Player (12'), B. Player (45')" : "👟 A. Player (12'), B. Player (45')";
                case "away-scorer": return locale === 'th' ? "👟 X. Player (30'), Y. Player (75')" : "👟 X. Player (30'), Y. Player (75')";
                default: break;
            }
        }
        if (b.shapeType === "text") return b.text || (locale === 'th' ? "ข้อความ" : "Text");
        return b.shapeType ? "" : getShortPreviewLabel(b.id);
    };

    return (
        <div className="md:col-span-6 lg:col-span-6.5 h-full flex flex-col min-h-0 relative">
            {/* Visual Dotted Grid Board */}
            <div
                onPointerDown={(e) => {
                    const activeEl = document.activeElement;
                    if (activeEl && (activeEl.tagName === "INPUT" || activeEl.tagName === "TEXTAREA")) {
                        (activeEl as HTMLElement).blur();
                    }
                    if (e.target === e.currentTarget) {
                        const rect = e.currentTarget.getBoundingClientRect();
                        const relX = e.clientX - rect.left;
                        const relY = e.clientY - rect.top;
                        setSelectionBox({ startX: relX, startY: relY, currentX: relX, currentY: relY, active: true });
                        setSelectedBlockId("");
                        try {
                            e.currentTarget.setPointerCapture(e.pointerId);
                        } catch (_err) { }
                    }
                }}
                onPointerMove={(e) => {
                    if (selectionBox?.active) {
                        const rect = e.currentTarget.getBoundingClientRect();
                        const currentX = e.clientX - rect.left;
                        const currentY = e.clientY - rect.top;
                        setSelectionBox(prev => prev ? { ...prev, currentX, currentY } : null);

                        const boxMinX = Math.min(selectionBox.startX, currentX) - rect.width / 2;
                        const boxMaxX = Math.max(selectionBox.startX, currentX) - rect.width / 2;
                        const boxMinY = Math.min(selectionBox.startY, currentY) - rect.height / 2;
                        const boxMaxY = Math.max(selectionBox.startY, currentY) - rect.height / 2;

                        const matchedIds = blocks.filter(b => b.active).filter(b => {
                            const bw = b.w || 100;
                            const bh = b.h || 40;
                            const bLeft = b.x - bw / 2;
                            const bRight = b.x + bw / 2;
                            const bTop = b.y - bh / 2;
                            const bBottom = b.y + bh / 2;
                            return !(bRight < boxMinX || bLeft > boxMaxX || bBottom < boxMinY || bTop > boxMaxY);
                        }).map(b => b.id);

                        setSelectedBlockId(matchedIds.join(","));
                    }
                }}
                onPointerUp={(e) => {
                    if (selectionBox?.active) {
                        try {
                            e.currentTarget.releasePointerCapture(e.pointerId);
                        } catch (_err) { }
                        setSelectionBox(null);
                    }
                }}
                className="w-full flex-1 h-full min-h-[500px] max-h-[82vh] border rounded-sm relative overflow-hidden flex items-center justify-center transition-colors duration-300 focus:outline-none"
                style={{
                    backgroundColor: bg === "transparent"
                        ? undefined
                        : bg === "chromakey"
                            ? "#00ff00"
                            : bg,
                    backgroundImage: `radial-gradient(${isLightColor(bg) ? "rgba(0,0,0,0.15)" : "rgba(255,255,255,0.08)"} 1px, transparent 1px)`,
                    backgroundSize: "16px 16px"
                }}
            >
                {/* Rubber-band Selection Box */}
                {selectionBox?.active && Math.abs(selectionBox.currentX - selectionBox.startX) > 2 && (
                    <div
                        className="absolute border border-primary bg-primary/20 backdrop-blur-[0.5px] pointer-events-none z-50 rounded-none"
                        style={{
                            left: `${Math.min(selectionBox.startX, selectionBox.currentX)}px`,
                            top: `${Math.min(selectionBox.startY, selectionBox.currentY)}px`,
                            width: `${Math.abs(selectionBox.currentX - selectionBox.startX)}px`,
                            height: `${Math.abs(selectionBox.currentY - selectionBox.startY)}px`,
                        }}
                    />
                )}

                {/* Active Alignment Guide Lines (Cyan Smart Snapping Guides) */}
                {activeGuideLines?.vLines.map((vX, i) => (
                    <div
                        key={`v-guide-${i}`}
                        className="absolute top-0 bottom-0 border-l-2 border-primary z-50 pointer-events-none"
                        style={{
                            left: `calc(50% + ${vX}px)`,
                        }}
                    />
                ))}
                {activeGuideLines?.hLines.map((hY, i) => (
                    <div
                        key={`h-guide-${i}`}
                        className="absolute left-0 right-0 border-t-2 border-primary z-50 pointer-events-none"
                        style={{
                            top: `calc(50% + ${hY}px)`,
                        }}
                    />
                ))}

                {/* Center Crosshair Reference */}
                <div className={`absolute top-1/2 left-0 right-0 border-b ${isLightColor(bg) ? "border-black/10" : "border-white/5"} pointer-events-none`} />
                <div className={`absolute left-1/2 top-0 bottom-0 border-l ${isLightColor(bg) ? "border-black/10" : "border-white/5"} pointer-events-none`} />

                {/* Bottom Center Floating Toolbar Menu */}
                <div className="absolute bottom-4 left-1/2 -translate-x-1/2 z-40 bg-card border shadow-xl rounded-sm p-1 flex items-center">
                    {/* Dropdown Shapes */}
                    <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                            <Button
                                type="button"
                                variant="ghost"
                                size="sm"
                                className="rounded h-8 px-2 text-xs font-bold gap-1.5 hover:bg-muted text-foreground"
                            >
                                <Shapes className="h-4 w-4" />
                                <span>{locale === 'th' ? "รูปทรง" : "Shapes"}</span>
                                <ChevronDown className="h-3 w-3 opacity-50" />
                            </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="center" side="top" sideOffset={8} className="bg-card border shadow-xl rounded-sm w-44">
                            <DropdownMenuItem onClick={() => handleAddShape("rectangle")} className="gap-2 rounded font-semibold text-xs cursor-pointer">
                                <Square className="h-4 w-4" />
                                <span>{locale === 'th' ? "สี่เหลี่ยม" : "Rectangle"}</span>
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => handleAddShape("circle")} className="gap-2 rounded font-semibold text-xs cursor-pointer">
                                <Circle className="h-4 w-4" />
                                <span>{locale === 'th' ? "วงกลม" : "Circle"}</span>
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => handleAddShape("polygon")} className="gap-2 rounded font-semibold text-xs cursor-pointer">
                                <Triangle className="h-4 w-4" />
                                <span>{locale === 'th' ? "Polygon (สามเหลี่ยม)" : "Polygon"}</span>
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => handleAddShape("star")} className="gap-2 rounded font-semibold text-xs cursor-pointer">
                                <Star className="h-4 w-4" />
                                <span>{locale === 'th' ? "ดาว" : "Star"}</span>
                            </DropdownMenuItem>
                        </DropdownMenuContent>
                    </DropdownMenu>

                    {/* Text Tool */}
                    <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        onClick={() => handleAddShape("text")}
                        className="rounded h-8 px-2 text-xs font-bold gap-1.5 hover:bg-muted text-foreground"
                    >
                        <Type className="h-4 w-4" />
                        <span>{locale === 'th' ? "ข้อความ" : "Text"}</span>
                    </Button>
                </div>

                {/* Render positioned Blocks */}
                {blocks.map((b, idx) => {
                    if (!b.active) return null;
                    const isSelected = selectedIds.includes(b.id);
                    const isScoreBlock = b.id === "score" || b.id === "score-home" || b.id === "score-away";
                    const blockBg = b.bg ?? (isScoreBlock ? scoreBg : "#000000");

                    const isCircle = b.shapeType === "circle";
                    const isPolygon = b.shapeType === "polygon";
                    const isStar = b.shapeType === "star";
                    const isText = b.shapeType === "text";
                    const strokePos = b.strokePos || "inside";
                    const strokeWidth = b.strokeWidth ?? 0;
                    const strokeInset = strokeWidth > 0
                        ? (strokePos === "outside" ? `-${strokeWidth}px` : strokePos === "center" ? `-${strokeWidth / 2}px` : "0px")
                        : "0px";

                    return (
                        <div
                            key={b.id}
                            onPointerDown={(e) => handlePointerDown(e, b.id)}
                            onPointerMove={(e) => handlePointerMove(e, b.id)}
                            onPointerUp={(e) => handlePointerUp(e, b.id)}
                            style={{
                                transform: `translate(calc(-50% + ${b.x}px), calc(-50% + ${b.y}px)) rotate(${b.rotation || 0}deg) scaleX(${b.flipX ? -1 : 1}) scaleY(${b.flipY ? -1 : 1})`,
                                left: "50%",
                                top: "50%",
                                width: isText ? "max-content" : `${b.w}px`,
                                height: isText ? "max-content" : `${b.h}px`,
                                fontSize: `${b.fontSize}px`,
                                borderTopLeftRadius: isCircle ? "50%" : `${b.rTL}px`,
                                borderTopRightRadius: isCircle ? "50%" : `${b.rTR}px`,
                                borderBottomLeftRadius: isCircle ? "50%" : `${b.rBL}px`,
                                borderBottomRightRadius: isCircle ? "50%" : `${b.rBR}px`,
                                color: b.color ?? "#ffffff",
                                touchAction: "none",
                                background: "transparent",
                                backgroundColor: "transparent",
                                isolation: "isolate",
                                zIndex: 10 + idx,
                                clipPath: isPolygon
                                    ? "polygon(50% 0%, 100% 100%, 0% 100%)"
                                    : isStar
                                        ? "polygon(50% 0%, 61% 35%, 98% 35%, 68% 57%, 79% 91%, 50% 70%, 21% 91%, 32% 57%, 2% 35%, 39% 35%)"
                                        : undefined,
                            }}
                            className={`absolute flex items-center justify-center font-black tracking-tight cursor-grab active:cursor-grabbing select-none transition-all duration-75 ${isSelected ? "z-20" : ""}`}
                        >
                            {/* Background container that supports opacity for gradient without fading text */}
                            <div
                                style={{
                                    position: "absolute",
                                    inset: strokeInset,
                                    transform: `skewX(${b.skewX || 0}deg) skewY(${b.skewY || 0}deg)`,
                                    zIndex: -1,
                                    borderRadius: isCircle ? "50%" : undefined,
                                    borderTopLeftRadius: isCircle ? "50%" : `${b.rTL}px`,
                                    borderTopRightRadius: isCircle ? "50%" : `${b.rTR}px`,
                                    borderBottomLeftRadius: isCircle ? "50%" : `${b.rBL}px`,
                                    borderBottomRightRadius: isCircle ? "50%" : `${b.rBR}px`,
                                    clipPath: isPolygon
                                        ? "polygon(50% 0%, 100% 100%, 0% 100%)"
                                        : isStar
                                            ? "polygon(50% 0%, 61% 35%, 98% 35%, 68% 57%, 79% 91%, 50% 70%, 21% 91%, 32% 57%, 2% 35%, 39% 35%)"
                                            : undefined,
                                    pointerEvents: "none",
                                    borderStyle: (b.strokeWidth ?? 0) > 0 ? "solid" : "none",
                                    borderWidth: (b.strokeWidth ?? 0) > 0 ? `${b.strokeWidth}px` : "0px",
                                    borderColor: b.strokeColor ?? "#ffffff",
                                    boxSizing: "border-box",
                                    ...(blockBg.includes("gradient") ? {
                                        background: blockBg,
                                        opacity: (b.opacity ?? 100) / 100,
                                    } : {
                                        backgroundColor: `color-mix(in srgb, ${blockBg} ${b.opacity ?? 100}%, transparent)`,
                                    })
                                }}
                            />
                            {/* Selection / Hover Outline frame that skews along with shape background */}
                            <div
                                className={`absolute inset-0 border pointer-events-none z-30 transition-all ${isSelected ? "border-2 border-primary" : "border-transparent hover:border-primary/60"}`}
                                style={{
                                    transform: `skewX(${b.skewX || 0}deg) skewY(${b.skewY || 0}deg)`,
                                    borderRadius: isCircle ? "50%" : undefined,
                                    borderTopLeftRadius: isCircle ? "50%" : `${b.rTL}px`,
                                    borderTopRightRadius: isCircle ? "50%" : `${b.rTR}px`,
                                    borderBottomLeftRadius: isCircle ? "50%" : `${b.rBL}px`,
                                    borderBottomRightRadius: isCircle ? "50%" : `${b.rBR}px`,
                                }}
                            />
                            <span
                                className={`${isText ? "whitespace-nowrap px-2 py-1" : "truncate px-1"} flex items-center gap-0.5`}
                                style={{
                                    fontWeight: b.fontWeight ?? undefined,
                                    fontStyle: b.fontStyle ?? "normal",
                                    textDecoration: b.textDecoration ?? "none",
                                }}
                            >
                                {getBlockDisplayContent(b)}
                            </span>
                            {b.id === "name-home" && homeBarDir !== "none" && (
                                <div
                                    style={{
                                        position: "absolute",
                                        [homeBarColor.includes("gradient") ? "background" : "backgroundColor"]: homeBarColor,
                                        ...(homeBarDir === "top" && { top: 0, left: 0, right: 0, height: "4px", borderTopLeftRadius: `${b.rTL}px`, borderTopRightRadius: `${b.rTR}px` }),
                                        ...(homeBarDir === "right" && { top: 0, bottom: 0, right: 0, width: "4px", borderTopRightRadius: `${b.rTR}px`, borderBottomRightRadius: `${b.rBR}px` }),
                                        ...(homeBarDir === "bottom" && { bottom: 0, left: 0, right: 0, height: "4px", borderBottomLeftRadius: `${b.rBL}px`, borderBottomRightRadius: `${b.rBR}px` }),
                                        ...(homeBarDir === "left" && { top: 0, bottom: 0, left: 0, width: "4px", borderTopLeftRadius: `${b.rTL}px`, borderBottomLeftRadius: `${b.rBL}px` }),
                                    }}
                                />
                            )}
                            {b.id === "name-away" && awayBarDir !== "none" && (
                                <div
                                    style={{
                                        position: "absolute",
                                        [awayBarColor.includes("gradient") ? "background" : "backgroundColor"]: awayBarColor,
                                        ...(awayBarDir === "top" && { top: 0, left: 0, right: 0, height: "4px", borderTopLeftRadius: `${b.rTL}px`, borderTopRightRadius: `${b.rTR}px` }),
                                        ...(awayBarDir === "right" && { top: 0, bottom: 0, right: 0, width: "4px", borderTopRightRadius: `${b.rTR}px`, borderBottomRightRadius: `${b.rBR}px` }),
                                        ...(awayBarDir === "bottom" && { bottom: 0, left: 0, right: 0, height: "4px", borderBottomLeftRadius: `${b.rBL}px`, borderBottomRightRadius: `${b.rBR}px` }),
                                        ...(awayBarDir === "left" && { top: 0, bottom: 0, left: 0, width: "4px", borderTopLeftRadius: `${b.rTL}px`, borderBottomLeftRadius: `${b.rBL}px` }),
                                    }}
                                />
                            )}
                        </div>
                    );
                })}
            </div>
        </div>
    );
}

import React, { useState } from "react";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Tab } from "@/components/ui/tab";
import {
    Sliders, Settings, Check, Copy, Eye, Link2, Trash2,
    MoveHorizontal, MoveVertical, RotateCw, FlipHorizontal2,
    FlipVertical2, SquareDashedBottom, CornerUpLeft, SquareRoundCorner,
    CornerUpRight, CornerDownLeft, CornerDownRight, Square, Circle, Group, Ungroup,
    Italic, Underline
} from "lucide-react";
import { CanvasBlock, BlankCanvas, DataBindType } from "./types";
import { DraggableLabel, GradientColorPicker } from "./helpers";
import { Header } from "@/components/ui/header";

interface EditorSidebarProps {
    blocks: CanvasBlock[];
    setBlocks: React.Dispatch<React.SetStateAction<CanvasBlock[]>>;
    selectedBlockId: string;
    setSelectedBlockId: (id: string) => void;
    selectedBlock?: CanvasBlock;
    updateCoordinates: (id: string, x: number, y: number) => void;
    updateBlockProperty: (id: string, props: Partial<CanvasBlock>) => void;
    blockGap: number;
    setBlockGap: (gap: number) => void;
    scoreBg: string;
    applyRadiiToAll: () => void;
    linkCorners: boolean;
    setLinkCorners: (val: boolean) => void;
    font: string;
    setFont: (font: string) => void;
    teamNameMode: "abbr" | "full";
    setTeamNameMode: (mode: "abbr" | "full") => void;
    homeBarDir: "none" | "top" | "right" | "bottom" | "left";
    setHomeBarDir: (dir: "none" | "top" | "right" | "bottom" | "left") => void;
    homeBarColor: string;
    setHomeBarColor: (color: string) => void;
    awayBarDir: "none" | "top" | "right" | "bottom" | "left";
    setAwayBarDir: (dir: "none" | "top" | "right" | "bottom" | "left") => void;
    awayBarColor: string;
    setAwayBarColor: (color: string) => void;
    posX: "left" | "center" | "right";
    setPosX: (pos: "left" | "center" | "right") => void;
    posY: "top" | "bottom";
    setPosY: (pos: "top" | "bottom") => void;
    bg: string;
    setBg: (bg: string) => void;
    locale: string;
    dict: Record<string, string>;

    // Config Tab Props
    selectedCanvasId: string;
    activeBlankCanvas?: BlankCanvas;
    blankCanvases: BlankCanvas[];
    setBlankCanvases: React.Dispatch<React.SetStateAction<BlankCanvas[]>>;
    setSelectedCanvasId: (id: string) => void;
    handleCanvasSwitch: (targetId: string) => void;
    scoreboardUrl: string;
    blankUrl: string;
    copiedScoreboard: boolean;
    copiedBlank: boolean;
    handleCopy: (url: string, type: "scoreboard" | "blank") => void;
    saveTemplate?: (showToast?: boolean) => void;
    saving?: boolean;
}

export function EditorSidebar({
    blocks,
    setBlocks,
    selectedBlockId,
    setSelectedBlockId,
    selectedBlock,
    updateCoordinates,
    updateBlockProperty,
    blockGap,
    setBlockGap,
    scoreBg,
    applyRadiiToAll,
    linkCorners,
    setLinkCorners,
    font,
    setFont,
    teamNameMode,
    setTeamNameMode,
    homeBarDir,
    setHomeBarDir,
    homeBarColor,
    setHomeBarColor,
    awayBarDir,
    setAwayBarDir,
    awayBarColor,
    setAwayBarColor,
    posX,
    setPosX,
    posY,
    setPosY,
    bg,
    setBg,
    locale,
    dict,
    selectedCanvasId,
    activeBlankCanvas,
    blankCanvases,
    setBlankCanvases,
    setSelectedCanvasId,
    handleCanvasSwitch,
    scoreboardUrl,
    blankUrl,
    copiedScoreboard,
    copiedBlank,
    handleCopy,
    saveTemplate,
    saving,
}: EditorSidebarProps) {
    const [activeTab, setActiveTab] = useState<"editor" | "config">("editor");

    const tabOptions = [
        {
            value: "editor" as const,
            label: locale === 'th' ? "ตัวแก้ไข (Editor)" : "Editor",
            icon: Sliders,
        },
        {
            value: "config" as const,
            label: locale === 'th' ? "การตั้งค่า (Config)" : "Config",
            icon: Settings,
        },
    ];

    return (
        <div className="md:col-span-3 flex flex-col gap-2 h-full max-h-[82vh] min-h-0">
            {/* Tab Navigation Header */}
            <Tab
                options={tabOptions}
                value={activeTab}
                onChange={setActiveTab}
                fullWidth
            />

            <div className="flex-1 overflow-y-auto min-h-0 pr-0.5 flex flex-col">
                {activeTab === "editor" ? (
                    <div className="flex-1 h-full flex flex-col border rounded-sm p-2 md:p-4 space-y-1 md:space-y-2 overflow-y-auto">
                        <div className="flex items-center justify-between">
                            <Header level={5}>{dict.pos_spacing}</Header>

                            <div className="flex items-center gap-1">
                                {/* Group / Ungroup Buttons */}
                                {(() => {
                                    const selectedIds = selectedBlockId.split(",").filter(Boolean);
                                    const isMulti = selectedIds.length > 1;
                                    const hasGroup = selectedIds.some(id => blocks.find(b => b.id === id)?.groupId);

                                    return (
                                        <>
                                            {isMulti && (
                                                <Button
                                                    type="button"
                                                    variant="ghost"
                                                    size="icon-sm"
                                                    onClick={() => {
                                                        const newGroupId = `group-${crypto.randomUUID()}`;
                                                        setBlocks(prev => prev.map(b => selectedIds.includes(b.id) ? { ...b, groupId: newGroupId } : b));
                                                    }}
                                                    title={locale === 'th' ? "รวมกลุ่ม (Ctrl+G)" : "Group (Ctrl+G)"}
                                                >
                                                    <Group className="h-4 w-4" />
                                                </Button>
                                            )}
                                            {hasGroup && (
                                                <Button
                                                    type="button"
                                                    variant="ghost"
                                                    size="icon-sm"
                                                    onClick={() => {
                                                        setBlocks(prev => prev.map(b => selectedIds.includes(b.id) ? { ...b, groupId: undefined } : b));
                                                    }}
                                                    title={locale === 'th' ? "ยกเลิกกลุ่ม (Ctrl+Shift+G)" : "Ungroup (Ctrl+Shift+G)"}
                                                >
                                                    <Ungroup className="h-4 w-4" />
                                                </Button>
                                            )}
                                        </>
                                    );
                                })()}

                                {/* Block Delete Button */}
                                {selectedBlock && selectedBlock.active && (
                                    <Button
                                        type="button"
                                        variant="ghost"
                                        size="icon-sm"
                                        onClick={() => {
                                            const ids = selectedBlockId.split(",").filter(Boolean);
                                            setBlocks(prev => prev.filter(b => !ids.includes(b.id)));
                                            setSelectedBlockId("");
                                        }}
                                        className="text-destructive"
                                        title={locale === 'th' ? "ลบ" : "Delete"}
                                    >
                                        <Trash2 className="h-4 w-4" />
                                    </Button>
                                )}
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-1 md:gap-2">
                            {/* X, Y Position Offset */}
                            {selectedBlock && (
                                <>
                                    <div className="flex items-center justify-between gap-2">
                                        <DraggableLabel value={selectedBlock.x} onChange={(val) => updateCoordinates(selectedBlockId, val, selectedBlock.y)} step={0.5}>{dict.x_offset}</DraggableLabel>
                                        <Input
                                            type="text"
                                            value={selectedBlock.x}
                                            onChange={(e) => {
                                                let clean = e.target.value.replace(/[^-0-9.]/g, "");
                                                if (clean.includes("-")) {
                                                    const isNegative = clean.startsWith("-");
                                                    clean = (isNegative ? "-" : "") + clean.replace(/-/g, "");
                                                }
                                                const dots = clean.split(".");
                                                if (dots.length > 2) {
                                                    clean = dots[0] + "." + dots.slice(1).join("");
                                                }
                                                updateCoordinates(selectedBlockId, clean === "" || clean === "-" || clean === "." ? 0 : Number(clean), selectedBlock.y);
                                            }}
                                            className="w-24 h-8 text-xs text-right"
                                        />
                                    </div>
                                    <div className="flex items-center justify-between gap-2">
                                        <DraggableLabel value={selectedBlock.y} onChange={(val) => updateCoordinates(selectedBlockId, selectedBlock.x, val)} step={0.5}>{dict.y_offset}</DraggableLabel>
                                        <Input
                                            type="text"
                                            value={selectedBlock.y}
                                            onChange={(e) => {
                                                let clean = e.target.value.replace(/[^-0-9.]/g, "");
                                                if (clean.includes("-")) {
                                                    const isNegative = clean.startsWith("-");
                                                    clean = (isNegative ? "-" : "") + clean.replace(/-/g, "");
                                                }
                                                const dots = clean.split(".");
                                                if (dots.length > 2) {
                                                    clean = dots[0] + "." + dots.slice(1).join("");
                                                }
                                                updateCoordinates(selectedBlockId, selectedBlock.x, clean === "" || clean === "-" || clean === "." ? 0 : Number(clean));
                                            }}
                                            className="w-24 h-8 text-xs text-right"
                                        />
                                    </div>
                                    <div className="flex items-center justify-between gap-2">
                                        <DraggableLabel value={selectedBlock.rotation || 0} onChange={(val) => updateBlockProperty(selectedBlockId, { rotation: val })} step={1}>
                                            <RotateCw className="h-4 w-4" />
                                        </DraggableLabel>
                                        <Input
                                            type="text"
                                            value={selectedBlock.rotation || 0}
                                            onChange={(e) => {
                                                let clean = e.target.value.replace(/[^-0-9.]/g, "");
                                                if (clean.includes("-")) {
                                                    const isNegative = clean.startsWith("-");
                                                    clean = (isNegative ? "-" : "") + clean.replace(/-/g, "");
                                                }
                                                const dots = clean.split(".");
                                                if (dots.length > 2) {
                                                    clean = dots[0] + "." + dots.slice(1).join("");
                                                }
                                                updateBlockProperty(selectedBlockId, { rotation: clean === "" || clean === "-" || clean === "." ? 0 : Number(clean) });
                                            }}
                                            className="w-24 h-8 text-xs text-right"
                                        />
                                    </div>
                                    <div className="flex items-center justify-end">
                                        <Button
                                            type="button"
                                            variant={selectedBlock.flipX ? "default" : "ghost"}
                                            size="icon"
                                            onClick={() => updateBlockProperty(selectedBlockId, { flipX: !selectedBlock.flipX })}
                                            title={locale === 'th' ? "พลิกแนวนอน" : "Flip Horizontal"}
                                        >
                                            <FlipHorizontal2 className="h-4 w-4" />
                                        </Button>
                                        <Button
                                            type="button"
                                            variant={selectedBlock.flipY ? "default" : "ghost"}
                                            size="icon"
                                            onClick={() => updateBlockProperty(selectedBlockId, { flipY: !selectedBlock.flipY })}
                                            title={locale === 'th' ? "พลิกแนวตั้ง" : "Flip Vertical"}
                                        >
                                            <FlipVertical2 className="h-4 w-4" />
                                        </Button>
                                    </div>
                                </>
                            )}

                            {/* Box Width */}
                            {selectedBlock && (
                                <div className="flex items-center justify-between gap-2">
                                    <DraggableLabel value={selectedBlock.w || 0} onChange={(val) => updateBlockProperty(selectedBlockId, { w: val })} min={0}>
                                        <MoveHorizontal className="h-4 w-4" />
                                    </DraggableLabel>
                                    <Input
                                        type="text"
                                        value={selectedBlock.w || ""}
                                        onChange={(e) => {
                                            const clean = e.target.value.replace(/[^0-9]/g, "");
                                            updateBlockProperty(selectedBlockId, { w: clean === "" ? 0 : Number(clean) });
                                        }}
                                        className="w-24 h-8 text-xs text-right"
                                    />
                                </div>
                            )}

                            {/* Box Height */}
                            {selectedBlock && (
                                <div className="flex items-center justify-between gap-2">
                                    <DraggableLabel value={selectedBlock.h || 0} onChange={(val) => updateBlockProperty(selectedBlockId, { h: val })} min={0}>
                                        <MoveVertical className="h-4 w-4" />
                                    </DraggableLabel>
                                    <Input
                                        type="text"
                                        value={selectedBlock.h || ""}
                                        onChange={(e) => {
                                            const clean = e.target.value.replace(/[^0-9]/g, "");
                                            updateBlockProperty(selectedBlockId, { h: clean === "" ? 0 : Number(clean) });
                                        }}
                                        className="w-24 h-8 text-xs text-right"
                                    />
                                </div>
                            )}

                            {/* Appearance Section */}
                            <div className="md:col-span-2 space-y-2 border-t pt-2 md:pt-4 mt-1 md:mt-2">
                                <Header level={5}>{dict.appearance}</Header>

                                {/* Opacity */}
                                {selectedBlock && (
                                    <div className="flex items-center justify-between gap-2">
                                        <DraggableLabel value={selectedBlock.opacity ?? 100} onChange={(val) => updateBlockProperty(selectedBlockId, { opacity: val })} min={0} max={100}>
                                            <SquareDashedBottom className="h-4 w-4" />
                                        </DraggableLabel>
                                        <Input
                                            type="text"
                                            value={selectedBlock.opacity ?? 100}
                                            onChange={(e) => {
                                                const clean = e.target.value.replace(/[^0-9]/g, "");
                                                let val = clean === "" ? 0 : Number(clean);
                                                val = Math.max(0, Math.min(100, val));
                                                updateBlockProperty(selectedBlockId, { opacity: val });
                                            }}
                                            className="w-24 h-8 text-xs text-right"
                                        />
                                    </div>
                                )}

                                {/* Corner Radius Section */}
                                {selectedBlock && (
                                    <div className="space-y-1.5">
                                        {/* Unified Corner Radius Row */}
                                        <div className="flex items-center justify-between gap-2">
                                            <DraggableLabel
                                                value={selectedBlock.rTL}
                                                onChange={(val) => updateBlockProperty(selectedBlockId, { rTL: val, rTR: val, rBL: val, rBR: val })}
                                                min={0}
                                            >
                                                <Square className="h-4 w-4" />
                                            </DraggableLabel>
                                            <div className="flex items-center">
                                                <Button
                                                    type="button"
                                                    variant={!linkCorners ? "default" : "ghost"}
                                                    size="icon"
                                                    onClick={() => setLinkCorners(!linkCorners)}
                                                    title={locale === 'th' ? "แยกปรับแต่ละมุม" : "Separate Corner Radii"}
                                                >
                                                    <SquareRoundCorner className="h-4 w-4" />
                                                </Button>
                                                <Input
                                                    type="text"
                                                    value={linkCorners ? selectedBlock.rTL : `${selectedBlock.rTL}/${selectedBlock.rTR}/${selectedBlock.rBL}/${selectedBlock.rBR}`}
                                                    onChange={(e) => {
                                                        const clean = e.target.value.replace(/[^0-9]/g, "");
                                                        const val = Number(clean) || 0;
                                                        updateBlockProperty(selectedBlockId, { rTL: val, rTR: val, rBL: val, rBR: val });
                                                    }}
                                                    disabled={!linkCorners}
                                                    className="w-24 h-8 text-xs text-right"
                                                />
                                            </div>
                                        </div>

                                        {/* Individual Corner Inputs (When Link Corners is OFF) */}
                                        {!linkCorners && (
                                            <div className="grid grid-cols-2 gap-1 lg:gap-2">
                                                {/* Top-Left */}
                                                <div className="flex items-center justify-between gap-1">
                                                    <DraggableLabel value={selectedBlock.rTL} onChange={(val) => updateBlockProperty(selectedBlockId, { rTL: val })} min={0}>
                                                        <CornerUpLeft className="h-4 w-4 text-muted-foreground" />
                                                    </DraggableLabel>
                                                    <Input
                                                        type="text"
                                                        value={selectedBlock.rTL}
                                                        onChange={(e) => {
                                                            const clean = e.target.value.replace(/[^0-9]/g, "");
                                                            updateBlockProperty(selectedBlockId, { rTL: Number(clean) || 0 });
                                                        }}
                                                        className="w-16 h-7 text-xs text-right"
                                                    />
                                                </div>
                                                {/* Top-Right */}
                                                <div className="flex items-center justify-between gap-1">
                                                    <DraggableLabel value={selectedBlock.rTR} onChange={(val) => updateBlockProperty(selectedBlockId, { rTR: val })} min={0}>
                                                        <CornerUpRight className="h-4 w-4 text-muted-foreground" />
                                                    </DraggableLabel>
                                                    <Input
                                                        type="text"
                                                        value={selectedBlock.rTR}
                                                        onChange={(e) => {
                                                            const clean = e.target.value.replace(/[^0-9]/g, "");
                                                            updateBlockProperty(selectedBlockId, { rTR: Number(clean) || 0 });
                                                        }}
                                                        className="w-16 h-7 text-xs text-right"
                                                    />
                                                </div>
                                                {/* Bottom-Left */}
                                                <div className="flex items-center justify-between gap-1">
                                                    <DraggableLabel value={selectedBlock.rBL} onChange={(val) => updateBlockProperty(selectedBlockId, { rBL: val })} min={0}>
                                                        <CornerDownLeft className="h-4 w-4 text-muted-foreground" />
                                                    </DraggableLabel>
                                                    <Input
                                                        type="text"
                                                        value={selectedBlock.rBL}
                                                        onChange={(e) => {
                                                            const clean = e.target.value.replace(/[^0-9]/g, "");
                                                            updateBlockProperty(selectedBlockId, { rBL: Number(clean) || 0 });
                                                        }}
                                                        className="w-16 h-7 text-xs text-right"
                                                    />
                                                </div>
                                                {/* Bottom-Right */}
                                                <div className="flex items-center justify-between gap-1">
                                                    <DraggableLabel value={selectedBlock.rBR} onChange={(val) => updateBlockProperty(selectedBlockId, { rBR: val })} min={0}>
                                                        <CornerDownRight className="h-4 w-4 text-muted-foreground" />
                                                    </DraggableLabel>
                                                    <Input
                                                        type="text"
                                                        value={selectedBlock.rBR}
                                                        onChange={(e) => {
                                                            const clean = e.target.value.replace(/[^0-9]/g, "");
                                                            updateBlockProperty(selectedBlockId, { rBR: Number(clean) || 0 });
                                                        }}
                                                        className="w-16 h-7 text-xs text-right"
                                                    />
                                                </div>
                                            </div>
                                        )}
                                    </div>
                                )}

                                {/* Fill Color Picker */}
                                {selectedBlock && (
                                    <GradientColorPicker
                                        label={dict.bg_color}
                                        value={selectedBlock.bg ?? (selectedBlockId.startsWith("score") ? scoreBg : "#000000")}
                                        onChange={(val) => updateBlockProperty(selectedBlockId, { bg: val })}
                                        fallbackColor="#000000"
                                    />
                                )}

                                {/* Stroke Section */}
                                {selectedBlock && (
                                    <div className="space-y-2">
