                                                            <SelectItem value="away-scorer">{locale === 'th' ? "👟 ผู้ทำประตูทีมเยือน" : "Away Scorer"}</SelectItem>
                                                        </>
                                                    )}
                                                </SelectContent>
                                            </Select>
                                        </div>
                                    );
                                })()}
