                                >
                                    {dict.abbr}
                                </button>
                                <button
                                    type="button"
                                    onClick={() => setTeamNameMode("full")}
                                    className={`px-2 py-1 rounded-sm border text-xs font-bold transition-all ${teamNameMode === "full"
